print("Checking if session has demos...")

if os.path.exists(found_path):
    with open(found_path) as f:
        content = f.read()

    # Look for any Demo pair text
    if "Demo pair" in content:
        # Extract demo data
        import re
        demos = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in content[m.end():].strip().split('\n')[:h]]
            if all(len(r) == w and all(c.isdigit() for r in rows for c in r)):
                demos[k] = [[int(c) for r in rows for c in r] for r in rows]

        print("\nDemos found:")
        for k, v in demos.items():
            print(f"{k}: {v}")
    else:
        print("No Demo pair text found in session")
else:
    print(f"File not found: {found_path}")

